import{bV as t,aL as o,u as a,G as l}from"./chunks/framework.DvBUyM1S.js";const m=JSON.parse('{"title":"DeepSeek Harness 设计哲学 · 思维框架","description":"","frontmatter":{"id":"PB-20260827-001","type":"playbook","title":"DeepSeek Harness 设计哲学 · 思维框架","tags":["deepseek-harness","architecture","design-philosophy","cordis"],"status":"draft","source":"conversation:2026-08-27","created":"2026-08-27T00:00:00.000Z","updated":"2026-08-27T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/harness-design-philosophy.md","filePath":"playbooks/harness-design-philosophy.md"}'),i={name:"playbooks/harness-design-philosophy.md"};function d(r,e,s,c,n,h){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="deepseek-harness-设计哲学-·-思维框架" tabindex="-1">DeepSeek Harness 设计哲学 · 思维框架 <a class="header-anchor" href="#deepseek-harness-设计哲学-·-思维框架" aria-label="Permalink to &quot;DeepSeek Harness 设计哲学 · 思维框架&quot;">​</a></h1><blockquote><p>蒸馏自 deepseek-harness 仓库文档（AGENTS.md / docs/architecture.md / cordis-primer / capability-seams / defensive-patterns / testing / packages/AGENTS.md）。用于在该 harness 中做设计决策、加能力、改扩展点、评审架构、写文档/Agent Note、选测试与推送前检查时调用。完整版 agent skill 存于 <code>deepseek-harness/.agents/skills/harness-framework/</code>（2026-08-27 已与原 <code>dsh-harness-framework</code> skill 合并，并入命令速查、反模式、价值排序、文档纪律、MM10-12）。</p></blockquote><h2 id="框架概览" tabindex="-1">框架概览 <a class="header-anchor" href="#框架概览" aria-label="Permalink to &quot;框架概览&quot;">​</a></h2><p>核心一句话：<strong>没有特权的核心，只有 Cordis 上下文 + 一串平等插件；一切行为都挂在文档化的扩展点上，并由可回滚的副作用注册。</strong></p><p>两条承重墙：</p><ol><li><strong>插件即架构</strong>。运行时由 <code>cordis.yml</code> 的 profile → bundle → 插件两层无环图组合而成。能力来自插件，不是写死在 spine。改 spine（尤其是 <code>agent-loop</code>）是 rare event，必须同步改 <code>docs/architecture.md</code>；加插件是常态。</li><li><strong>会话日志是唯一真相源</strong>。任何&quot;模型可见&quot;的输入都必须能从会话日志重建；fork、resume、transcript、遥测全部派生自此流。模型可见 ⟺ 已记录。</li></ol><h2 id="心智模型-mental-models" tabindex="-1">心智模型（Mental Models） <a class="header-anchor" href="#心智模型-mental-models" aria-label="Permalink to &quot;心智模型（Mental Models）&quot;">​</a></h2><h3 id="mm1-—-没有特权的核心-一切皆插件" tabindex="-1">MM1 — 没有特权的核心：一切皆插件 <a class="header-anchor" href="#mm1-—-没有特权的核心-一切皆插件" aria-label="Permalink to &quot;MM1 — 没有特权的核心：一切皆插件&quot;">​</a></h3><ul><li>扩展 = 把插件挂到别的插件旁边，不是打补丁核心。能力默认来自插件。</li><li>思考&quot;功能放哪&quot;时默认答案：新插件/新 bundle，不是改 spine。</li></ul><h3 id="mm2-—-注册即可逆副作用" tabindex="-1">MM2 — 注册即可逆副作用 <a class="header-anchor" href="#mm2-—-注册即可逆副作用" aria-label="Permalink to &quot;MM2 — 注册即可逆副作用&quot;">​</a></h3><ul><li>提示段、工具 schema、适配器、监听器都经 <code>ctx.effect()</code> / <code>ctx.on()</code> 注册，卸载时统一回滚，每个注册返回 disposer。</li><li>测试中必须证明销毁（HMR-safety）。</li></ul><h3 id="mm3-—-能力缝合-定义-提供-消费-三者齐备" tabindex="-1">MM3 — 能力缝合 = 定义 + 提供 + 消费（三者齐备） <a class="header-anchor" href="#mm3-—-能力缝合-定义-提供-消费-三者齐备" aria-label="Permalink to &quot;MM3 — 能力缝合 = 定义 + 提供 + 消费（三者齐备）&quot;">​</a></h3><ul><li>一个&quot;缝合点&quot;是可替换能力，由 Service Definition + Provider + Consumer 三角色组成，缺一不算缝合点。三角色分处不同包，当且仅当各自独立演化。</li><li>为<strong>所有当前 Consumer</strong> 设计 SD；不让单个 Consumer 独裁契约。</li></ul><h3 id="mm4-—-模型可见-⟺-已记录" tabindex="-1">MM4 — 模型可见 ⟺ 已记录 <a class="header-anchor" href="#mm4-—-模型可见-⟺-已记录" aria-label="Permalink to &quot;MM4 — 模型可见 ⟺ 已记录&quot;">​</a></h3><ul><li>任何到达模型请求的输入必须能从会话日志重建。新增模型可见输入 ⇒ 新增会话事件。<code>deriveMessages()</code> 从日志投影历史。</li></ul><h3 id="mm5-—-事件是扩展点-waterfall-必须-next" tabindex="-1">MM5 — 事件是扩展点，waterfall 必须 next() <a class="header-anchor" href="#mm5-—-事件是扩展点-waterfall-必须-next" aria-label="Permalink to &quot;MM5 — 事件是扩展点，waterfall 必须 next()&quot;">​</a></h3><ul><li>会话事件（持久可回放）/代理事件（实时可丢）/能力事件（策略/适配）三族分层。Waterfall 监听器<strong>必须调 <code>next()</code></strong> 委托，否则短路整条链。封闭联合以 <code>assertNever</code> 收尾，可扩展联合走 documented default。</li></ul><h3 id="mm6-—-显式优于隐式-包边界铁律" tabindex="-1">MM6 — 显式优于隐式（包边界铁律） <a class="header-anchor" href="#mm6-—-显式优于隐式-包边界铁律" aria-label="Permalink to &quot;MM6 — 显式优于隐式（包边界铁律）&quot;">​</a></h3><ul><li>部署可变的取舍是经验证的 <code>Config</code> 字段，可从 cordis.yml 改。<code>DEFAULT_*</code> 常量或测试钩子<strong>不是</strong>可配置性。默认化是拥有方实现里的显式 <code>resolve(request): Spec</code> 步骤，不是 <code>run()</code> 里藏 <code>?? default</code>。</li></ul><h3 id="mm7-—-同进程信任类型-边界处校验" tabindex="-1">MM7 — 同进程信任类型，边界处校验 <a class="header-anchor" href="#mm7-—-同进程信任类型-边界处校验" aria-label="Permalink to &quot;MM7 — 同进程信任类型，边界处校验&quot;">​</a></h3><ul><li>静态接口已要求的返回值不加运行时校验/fallback。只在 parser/config、queued、model/tool JSON、durable/file、worker、process、wire 这些边界校验。</li></ul><h3 id="mm8-—-善终优先-销毁要到静默" tabindex="-1">MM8 — 善终优先：销毁要到静默 <a class="header-anchor" href="#mm8-—-善终优先-销毁要到静默" aria-label="Permalink to &quot;MM8 — 善终优先：销毁要到静默&quot;">​</a></h3><ul><li>清理要异步，<code>kill → await done</code>，并在 kill 前关闭监听/通知注册表，让迟到完成保持静默。正交结果（<code>timedOut</code>/<code>signal</code>/<code>exitCode</code>）独立上报，绝不嵌套。异步状态不是同步状态。</li></ul><h3 id="mm9-—-地基优于兼容壳-发布前姿态" tabindex="-1">MM9 — 地基优于兼容壳（发布前姿态） <a class="header-anchor" href="#mm9-—-地基优于兼容壳-发布前姿态" aria-label="Permalink to &quot;MM9 — 地基优于兼容壳（发布前姿态）&quot;">​</a></h3><ul><li>无外部消费者时优先正确地基而非兼容垫片。可自由重命名/重打包但要把每个引用一起更新。后端拒绝旧的磁盘格式；schema 版本单调。</li></ul><h3 id="mm10-—-双层-scope-模型" tabindex="-1">MM10 — 双层 Scope 模型 <a class="header-anchor" href="#mm10-—-双层-scope-模型" aria-label="Permalink to &quot;MM10 — 双层 Scope 模型&quot;">​</a></h3><ul><li>贡献分 global 与 scoped 两级，scoped 不向下继承；live agent 是自身 scope 的 key（对象身份比较）。</li><li>做 per-agent 变体/工具限制/persona 用 scope 机制而非全局判断；subtree 行为用 lineage 数据表达，不用 scope 结构。</li></ul><h3 id="mm11-—-工具执行管线" tabindex="-1">MM11 — 工具执行管线 <a class="header-anchor" href="#mm11-—-工具执行管线" aria-label="Permalink to &quot;MM11 — 工具执行管线&quot;">​</a></h3><ul><li>工具调用经 pre-execute（waterfall）→ guards（单调，deny or abstain）→ approval（缺省 deny）→ execute（around dispatch）→ 工具体 → post-execute → 归一化 → finalizeContent → result 的受守护管线。</li><li>跨工具家族策略（权限/超时/审批/上下文注入）挂 waterfall/guards，不写死在单个工具里。</li></ul><h3 id="mm12-—-防御模式-bug-类规则" tabindex="-1">MM12 — 防御模式（bug 类规则） <a class="header-anchor" href="#mm12-—-防御模式-bug-类规则" aria-label="Permalink to &quot;MM12 — 防御模式（bug 类规则）&quot;">​</a></h3><ul><li>真实出过事的缺陷类：正交结果独立报告、公共契约双端遵守、异步状态不是同步状态、Dispose 须达静默、回调异常隔离、环境 scrubbed、链接形路径 unlink。</li><li>写生命周期/并发/子进程/teardown 前必读 <code>docs/defensive-patterns.md</code>。</li></ul><h2 id="决策启发式-decision-heuristics" tabindex="-1">决策启发式（Decision Heuristics） <a class="header-anchor" href="#决策启发式-decision-heuristics" aria-label="Permalink to &quot;决策启发式（Decision Heuristics）&quot;">​</a></h2><h3 id="架构与设计" tabindex="-1">架构与设计 <a class="header-anchor" href="#架构与设计" aria-label="Permalink to &quot;架构与设计&quot;">​</a></h3><ul><li>要加新能力 → 先画 SD/Provider/Consumer 三角；为所有当前 Consumer 设计 SD。</li><li>某物会到达模型 → 加一条会话事件，确保能从日志重建。</li><li>要改 <code>agent-loop</code> → 先更新 <code>docs/architecture.md</code>，再动代码。</li><li>引入可变开关/默认 → 做成 <code>Config</code> 字段 + 显式 <code>resolve(request): Spec</code>，别用 <code>?? default</code> 藏进 <code>run()</code>。</li><li>跨边界 id → 用 <code>Branded&lt;B&gt;</code>，不用裸 <code>string</code>。</li><li>错误配置 fail loud：自包含配置 load 时失败，否则最早可解析点失败；绝不静默跳过缺失引用。</li><li>新行为 → 挂到文档化扩展点；不确定有没有扩展点就先查 <code>docs/architecture.md</code>。</li></ul><h3 id="代码与边界" tabindex="-1">代码与边界 <a class="header-anchor" href="#代码与边界" aria-label="Permalink to &quot;代码与边界&quot;">​</a></h3><ul><li>校验该不该加 → 在 7 类边界加；同进程类型化值不加。</li><li>空 catch 必须命名：说明吞掉什么、为何其他异常到不了这里；try 只包一条语句。</li><li>运行时 invariant 断言<strong>拥有的关系</strong>（权威事件流/可变数据），不检查服务存在性/插件元数据/固定纯样例。</li><li>可选依赖用 <code>ctx.get(name)</code>，不靠 <code>ctx.&amp;lt;name&amp;gt;</code> 属性代理。</li><li>平行值要对称；无法解释的非对称通常意味着漏了一个抽取。</li></ul><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h3><ul><li>测试策略 → 真实入口路径 + 无 key 快照覆盖模型/协议/人可见输出 + 验证&quot;世界&quot;而非自报。</li><li>测试选最小相关集；覆盖率聚焦受影响源（<code>--coverage.include=&#39;packages/&amp;lt;g&amp;gt;/&lt;p&gt;/src/**/*.ts&#39;</code>，禁 <code>--passWithNoTests</code>/压低阈值/收窄 include）。</li><li>边界作用在完整结果上：字节/token/条目/时间限制在完整 emit 值处强制。</li><li>状态只在提交点发布：操作成功后才发通知/更新派生状态。</li></ul><h3 id="文档与推送" tabindex="-1">文档与推送 <a class="header-anchor" href="#文档与推送" aria-label="Permalink to &quot;文档与推送&quot;">​</a></h3><ul><li>非平凡改动 → 同 PR 写 Agent Note；改了过时行为要改其测试并解释。</li><li>文档是变更的一部分：行为改变同步更新 README 与 JSDoc；<code>ts type-equiv</code> 粘贴块在 manifest 注册。</li><li>历史改写必须 lease 保护：<code>--force-with-lease=&amp;lt;branch&amp;gt;:&amp;lt;observed-oid&amp;gt;</code>，裸 <code>--force</code> 永不使用。</li><li>本地失败先修再推，不&quot;push and hope&quot;。</li></ul><h2 id="命令速查" tabindex="-1">命令速查 <a class="header-anchor" href="#命令速查" aria-label="Permalink to &quot;命令速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>命令</th></tr></thead><tbody><tr><td>安装（含钩子）</td><td><code>pnpm install</code></td></tr><tr><td>类型检查</td><td><code>pnpm run typecheck</code></td></tr><tr><td>构建</td><td><code>pnpm run build</code> / <code>pnpm run build:official</code></td></tr><tr><td>文档同步门禁</td><td><code>pnpm run doc-sync</code></td></tr><tr><td>全套本地门禁</td><td><code>pnpm run check:all</code></td></tr><tr><td>e2e</td><td><code>pnpm run test:e2e</code>（需 DEEPSEEK_API_KEY，无 key self-skip）</td></tr><tr><td>单测+覆盖率</td><td><code>pnpm exec vitest run &amp;lt;tests/file.spec.ts&amp;gt; --coverage --coverage.include=&#39;packages/&amp;lt;g&amp;gt;/&lt;p&gt;/src/**/*.ts&#39;</code></td></tr><tr><td>变更范围</td><td><code>pnpm --silent run change-scope --base &amp;lt;ref&amp;gt;</code></td></tr></tbody></table><h2 id="反模式-avoid" tabindex="-1">反模式（Avoid） <a class="header-anchor" href="#反模式-avoid" aria-label="Permalink to &quot;反模式（Avoid）&quot;">​</a></h2><ul><li>用 TS interface 定义 Service Definition（须 abstract class 或 concrete registry）。</li><li>让一个 Consumer 独裁服务契约；公共服务方法只有一个内部调用者。</li><li>直接改 core/agent-loop 而不找扩展点；改了不更新 <code>docs/architecture.md</code>。</li><li>跳过 Agent Note 的非平凡变更；编辑已归档的 note。</li><li>模型可见产物写在不进日志的地方。</li><li>mock 优先于真实实现；断言自报告而非世界效果。</li><li>反射性全量跑测试。</li><li>提交点前发通知/更新状态；派生数据各自维护副本。</li><li>空 catch；凭据环境传给 spawn；可预测路径存 temp/spill 文件。</li><li>递归 rmSync 删 symlink/junction；裸 <code>--force</code> push。</li><li>文档与代码漂移（type-equiv 未注册、manifest 未更新、双语不对齐）。</li><li>类型边界加运行时校验；wire/持久化 id 用裸 string。</li><li>在 <code>run()</code> 内隐藏默认值；错误配置静默跳过。</li><li>PR 缺 kind/area label；TODO/FIXME/XXX 不按紧急度标记。</li></ul><h2 id="价值排序" tabindex="-1">价值排序 <a class="header-anchor" href="#价值排序" aria-label="Permalink to &quot;价值排序&quot;">​</a></h2><ol><li><strong>可验证性</strong>：一切判断可被 gate/测试/日志验证。</li><li><strong>可逆性</strong>：注册即 effect，所有变更可 dispose/回滚。</li><li><strong>显式性</strong>：声明式、可 grep，优于隐式魔法。</li><li><strong>最小表面</strong>：只为当前消费者设计，不预设未来。</li><li><strong>文档纪律</strong>：决策、文档、代码三者同步。</li></ol><h2 id="流派-张力对比-schools-tensions" tabindex="-1">流派 / 张力对比（Schools &amp; Tensions） <a class="header-anchor" href="#流派-张力对比-schools-tensions" aria-label="Permalink to &quot;流派 / 张力对比（Schools &amp; Tensions）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>张力</th><th>一端</th><th>另一端</th><th>默认落点</th></tr></thead><tbody><tr><td>插件纯度 vs 产品务实</td><td>一切都拆成独立包/三角色</td><td>能一起变就同目录、少抽象</td><td>看演化独立性（MM3）</td></tr><tr><td>静态信任 vs 边界校验</td><td>同进程信任 TypeScript</td><td>在 7 类边界强硬校验</td><td>按边界类型分流（MM7）</td></tr><tr><td>地基 vs 兼容壳</td><td>做对、自由改名</td><td>保留兼容垫片</td><td>发布前优先地基（MM9）</td></tr><tr><td>显式 vs 简洁</td><td>一切走 <code>Config</code>/<code>resolve</code></td><td>少写样板</td><td>部署可变者必显式（MM6）</td></tr><tr><td>模型可见自由 vs 日志纪律</td><td>想加啥加啥</td><td>凡模型可见必入日志</td><td>日志纪律优先（MM4）</td></tr><tr><td>能力集中 vs 消费方自治</td><td>SD 定义全契约</td><td>Consumer 各自扩展</td><td>SD 为所有 Consumer 设计</td></tr></tbody></table><p>评审时用第二、三列框定争论，再用&quot;默认落点&quot;收口。</p><h2 id="应用工作流-设计决策协议" tabindex="-1">应用工作流（设计决策协议） <a class="header-anchor" href="#应用工作流-设计决策协议" aria-label="Permalink to &quot;应用工作流（设计决策协议）&quot;">​</a></h2><ol><li><strong>归类</strong>：能力 / 扩展点 / 生命周期 / 配置？对应 MM1–MM12 哪条？</li><li><strong>找扩展点</strong>：查 <code>docs/architecture.md</code>，确认有没有现成扩展点能承载；没有才考虑 spine 改动（并同步文档）。</li><li><strong>画三角</strong>：若是能力，列 SD / Provider / Consumer，确认每角归属与当前 Consumer 证据。</li><li><strong>查模型可见性</strong>：会出现在 prompt/tool/结果里吗？会 → 加会话事件，确保可重建。</li><li><strong>定边界</strong>：可变开关 → <code>Config</code> + <code>resolve</code>；跨边界 id → <code>Branded</code>；校验只在 7 类边界。</li><li><strong>想善终</strong>：有生命周期/并发 → 按 <code>docs/defensive-patterns.md</code> 设计到静默的销毁与正交上报。</li><li><strong>验世界</strong>：规划测试——真实入口路径 + 无 key 快照 + 世界验证；同 PR 补 Agent Note。</li><li><strong>对称自查</strong>：平行值是否对称？非对称是否意味着漏了一个抽取？</li><li><strong>过门禁</strong>：按变更面选最小检查（见命令速查），文档/契约变更跑 <code>doc-sync</code>；本地失败先修再推。</li></ol><h2 id="文档与-agent-note-纪律" tabindex="-1">文档与 Agent Note 纪律 <a class="header-anchor" href="#文档与-agent-note-纪律" aria-label="Permalink to &quot;文档与 Agent Note 纪律&quot;">​</a></h2><ul><li><strong>文档分级</strong>：先判断读者与用途再选层级；避免 slop（空话/过度营销）；注意字数预算；双语 <code>.zh.md</code> 结构逐节对应、token 保持英文原样。</li><li><strong><code>ts type-equiv</code></strong>：粘贴源码等价声明用 <code>```ts type-equiv</code> 围栏 + 在 <code>scripts/type-equiv.manifest.json</code> 注册 symbol；类实现体不进 catalog 用 <code>```ts public-api</code>。改动被文档化的声明必须同步更新粘贴块与 manifest。</li><li><strong>Agent Note</strong>：非平凡变更 MUST 同 PR 写 note；路径 <code>{lifecycle}/{class}/yyyy-mm-dd-topic-title.md</code>；implemented 用 <code>## Problem</code> → <code>## Decision</code>（现在时）→ <code>## Alternatives considered</code> → <code>## Consequences</code>，禁止 Proposal/Plan/Acceptance criteria；<code>## Alternatives considered</code> 强制；归档 note 永久冻结，不编辑。</li></ul><h2 id="诚实边界" tabindex="-1">诚实边界 <a class="header-anchor" href="#诚实边界" aria-label="Permalink to &quot;诚实边界&quot;">​</a></h2><ul><li>这是<strong>发布前</strong>哲学：明确偏好地基而非兼容，外部消费者出现后部分取舍会变。</li><li>高度 opinionated，假设你在同仓工作、熟悉 Cordis 与 TypeScript 严格模式；跨仓/跨语言需裁剪。</li><li>框架给方向，不给具体 API 签名；落实到代码前以当前 <code>docs/</code> 与源码为准。</li><li>&quot;张力对比&quot;里的&quot;默认落点&quot;是倾向，不是规则；用证据（当前 Consumer、演化独立性）推翻它。</li><li>命令与 gate 清单会随仓库演进，以 <code>package.json</code> 与 <code>scripts/run-gates.ts</code> 为准。</li></ul><h2 id="智识谱系" tabindex="-1">智识谱系 <a class="header-anchor" href="#智识谱系" aria-label="Permalink to &quot;智识谱系&quot;">​</a></h2><ul><li><strong>Cordis（vendored）</strong>：插件上下文 + 声明合并 + 可逆副作用，脊梁直接来源。</li><li><strong>事件溯源</strong>：会话日志作为唯一真相源、<code>deriveMessages</code> 投影。</li><li><strong>基于能力的架构</strong>：能力缝合三角色、可替换 Provider。</li><li><strong>插件 / 微内核架构</strong>：&quot;没有特权的核心&quot;。</li><li><strong>静态类型即规范</strong>：类型化同进程边界信任编译器。</li></ul>',57)])])}const p=t(i,[["render",d]]);export{m as __pageData,p as default};
